<script>
import blueprints from '../data/blueprints.json';
import { validate } from '../lib/invariants';
import { render } from '../lib/renderManifest';
import { isAllowed } from '../lib/gate';
import {
  listCloudCredentials,
  listRke2Versions,
  listHarvesterSiteResources,
  discoverZoneCeph,
  discoverVsphereInventory,
  postMachineConfig,
  postCluster,
  getClusterStatus,
} from '../lib/steve';

function defaultZone(zone, provider = 'harvester') {
  return {
    zone,
    provider,
    credentialId: '',
    // --- Harvester (provider='harvester') ---
    vmNamespace:  'default',
    networkName:  'shared-k8s/fcs-backend-vm-net',
    image:        '',
    // Node-Root-Storage der Site: 'longhorn' (Default, image) oder 'ceph' (cephImage,
    // Root-PVC auf Rook-Ceph-RBD via VMImage.targetStorageClassName + backend=cdi).
    nodeStorage:  'longhorn',
    cephImage:    '',
    // EFI-Boot pro Zone setzbar — image-/insel-abhängig (PoC-Befund: gleiches
    // Leap-Micro-Image bootete dev nur mit false, DC2 mit true; Root-Cause offen).
    enableEfi:    true,
    // --- vSphere (provider='vsphere', z.B. HAN-Witness) ---
    vsphere: {
      datacenter: '', datastore: '', datastoreCluster: '', pool: '', folder: '',
      network: '', cloneFrom: '', os: 'linux',
      // Static-IP für Segmente OHNE DHCP (leer = DHCP): cloud-init network-config v2
      // via guestinfo.metadata; dns als Array (UI bindet CSV, s. setVsphereDns).
      staticIp: '', prefix: 24, gateway: '', dns: [],
    },
    sshUser:      'sles',
    cpu:          4,
    mem:          8,
    disk:         40,
    cpQuantity:   zone === 'b1' ? 2 : 1,
    workerCount:  1,
    etcdOnly:     false,
  };
}

export default {
  name:   'ProvisionWizard',
  layout: 'plain',

  data() {
    return {
      spec: {
        name:        'sfh-stretch-poc',
        k8sVersion:  blueprints.defaultK8sVersion,
        podCidr:     blueprints.defaultPodCidr,
        serviceCidr: blueprints.defaultServiceCidr,
        routingMode: 'tunnel',
        zones:       [defaultZone('b1'), defaultZone('b2')],
        // Optionales Gast-Workload-Storage (ceph-csi-rbd, zonale SCs) — null = aus.
        workloadCeph: null,
      },
      credentials:  [],
      k8sVersions:  [],
      // Site-Ressourcen je Credential (Cache): { images, networks, namespaces, loading }.
      // Fehlgeschlagene Loads degradieren zu leeren Listen → Wizard zeigt Freitext-Inputs
      // (fail-open UI; die harten Gates bleiben die Invarianten).
      siteCache:    {},
      // vCenter-Inventar je vSphere-Credential (Dropdowns der Platzierung):
      // { [credId]: { dataCenters, loading, byDc: { [dc]: { dataStores, dataStoreClusters,
      //   pools, folders, networks, templates, loading } } } } — fail-open (leer = Freitext).
      vsphereCache: {},
      errors:       [],
      log:          [],
      busy:         false,
      loadingCreds: true,
      isAdmin:      true,
    };
  },

  async mounted() {
    // Admin-Gate auf die Aktion (nicht auf die Nav): isAdminUser greift hier korrekt,
    // weil die management-Schemas zur Nav-Zeit geladen sind.
    this.isAdmin = isAllowed(this.$store);
    try {
      const [creds, vers] = await Promise.all([
        listCloudCredentials(this.$store),
        listRke2Versions(this.$store),
      ]);
      this.credentials = creds;
      this.k8sVersions = vers;
    } catch (e) {
      this.errors = [`Cloud-Credentials konnten nicht geladen werden: ${ e?.message || e }`];
    } finally {
      this.loadingCreds = false;
    }
  },

  methods: {
    // Credentials passend zum Provider der Zone (Harvester-Insel vs. vSphere/vCenter).
    credsForProvider(provider) {
      const want = provider === 'vsphere' ? 'vmwarevsphere' : 'harvester';
      return this.credentials.filter((c) => c.provider === want);
    },
    // Site-Ressourcen der Zone (aus dem Cache; leeres Objekt solange nichts geladen).
    siteFor(z) {
      return this.siteCache[z.credentialId] || { images: [], networks: [], namespaces: [], loading: false };
    },
    // vCenter-Inventar der Zone (aus dem Cache; leere Struktur solange nichts geladen).
    vsFor(z) {
      return this.vsphereCache[z.credentialId] || { dataCenters: [], byDc: {}, loading: false };
    },
    vsDcFor(z) {
      const dc = `${ z.vsphere?.datacenter || '' }`.trim();
      return this.vsFor(z).byDc[dc] || {
        dataStores: [], dataStoreClusters: [], pools: [], folders: [], networks: [], templates: [], loading: false,
      };
    },
    // vSphere-Credential gewählt/gewechselt: Platzierung KOMPLETT invalidieren (sonst
    // rendert render() stale Werte der alten Site, CMR-P2), Datacenter-Liste laden
    // (in-flight über _vsPending dedupliziert — auch für eine zweite Zone mit demselben
    // Credential, CMR-P2-Race), bei genau EINEM Datacenter Autoselect + Ressourcen laden.
    async onVsphereCredentialChange(z) {
      const credId = z.credentialId;
      // Auch Static-IP/DNS invalidieren: die Werte sind netz-/DC-abhängig und würden
      // sonst als guestinfo.metadata auf der NEUEN PortGroup landen (CMR-R2-P2).
      Object.assign(z.vsphere, {
        datacenter: '', datastore: '', datastoreCluster: '', pool: '', folder: '', network: '', cloneFrom: '',
        staticIp: '', gateway: '', dns: [], prefix: 24,
      });
      if (!credId) {
        return;
      }
      this._vsPending = this._vsPending || {};
      if (!this.vsphereCache[credId] && !this._vsPending[credId]) {
        this.vsphereCache = { ...this.vsphereCache, [credId]: { dataCenters: [], byDc: {}, loading: true } };
        this._vsPending[credId] = discoverVsphereInventory(this.$store, credId)
          .then((inv) => {
            // byDc aus dem AKTUELLEN Cache bewahren — ein parallel gelaufener DC-Load
            // darf nicht durch `byDc: {}` verloren gehen (CMR-P2-Race).
            const cur = this.vsphereCache[credId] || { byDc: {} };
            this.vsphereCache = {
              ...this.vsphereCache,
              [credId]: { dataCenters: inv.dataCenters || [], byDc: cur.byDc || {}, loading: false },
            };
          })
          .finally(() => {
            delete this._vsPending[credId];
          });
      }
      if (this._vsPending[credId]) {
        await this._vsPending[credId];
      }
      // Stale-Guard: während des Loads kann das Credential erneut gewechselt worden sein —
      // dann gehören Autoselect/Ressourcen-Load nicht mehr zu dieser Zone (CMR-R2-P2).
      if (z.credentialId !== credId) {
        return;
      }
      const dcs = (this.vsphereCache[credId] || {}).dataCenters || [];
      if (dcs.length === 1 && !`${ z.vsphere.datacenter || '' }`.trim()) {
        z.vsphere.datacenter = dcs[0];
      }
      return this.loadVsphereDcResources(z);
    },
    // Explizite Datacenter-Wahl im UI: DC-abhängige Felder invalidieren (CMR-P2) + laden.
    // Static-IP/DNS ebenfalls — netz-abhängig, sonst landet die alte IP auf der neuen
    // PortGroup (CMR-R2-P2).
    onVsphereDatacenterChange(z) {
      Object.assign(z.vsphere, {
        datastore: '', datastoreCluster: '', pool: '', folder: '', network: '', cloneFrom: '',
        staticIp: '', gateway: '', dns: [], prefix: 24,
      });
      return this.loadVsphereDcResources(z);
    },
    // Loader OHNE Feld-Reset (auch vom Autoselect-/Zweit-Zonen-Pfad genutzt);
    // je credId+DC gecacht und in-flight dedupliziert.
    async loadVsphereDcResources(z) {
      const credId = z.credentialId;
      const dc = `${ z.vsphere?.datacenter || '' }`.trim();
      if (!credId || !dc) {
        return;
      }
      const key = `${ credId }|${ dc }`;
      this._vsPending = this._vsPending || {};
      if (this._vsPending[key]) {
        return this._vsPending[key];
      }
      const cache = this.vsphereCache[credId] || { dataCenters: [], byDc: {}, loading: false };
      if (cache.byDc[dc]) {
        return;
      }
      const empty = {
        dataStores: [], dataStoreClusters: [], pools: [], folders: [], networks: [], templates: [],
      };
      this.vsphereCache = {
        ...this.vsphereCache,
        [credId]: { ...cache, byDc: { ...cache.byDc, [dc]: { ...empty, loading: true } } },
      };
      this._vsPending[key] = discoverVsphereInventory(this.$store, credId, dc)
        .then((res) => {
          const cur = this.vsphereCache[credId] || { dataCenters: [], byDc: {}, loading: false };
          this.vsphereCache = {
            ...this.vsphereCache,
            [credId]: { ...cur, byDc: { ...cur.byDc, [dc]: { ...empty, ...res, loading: false } } },
          };
        })
        .finally(() => {
          delete this._vsPending[key];
        });
      return this._vsPending[key];
    },
    // Credential gewählt → Site-Ressourcen (Images/NADs/Namespaces) über den
    // Rancher-Proxy der Harvester-Insel laden (einmalig je Credential, gecacht).
    async onCredentialChange(z) {
      // vSphere ZUERST (auch bei geleertem Credential): onVsphereCredentialChange leert
      // die Platzierung immer — sonst bliebe sie nach Abwahl sichtbar (CMR-R2-P3).
      if (z.provider === 'vsphere') {
        return this.onVsphereCredentialChange(z);
      }
      if (!z.credentialId) {
        return;
      }
      if (z.provider !== 'harvester') {
        return;
      }
      const credId = z.credentialId;
      if (this.siteCache[credId]) {
        return;
      }
      const cred = this.credentials.find((c) => c.id === credId);
      const clusterId = cred?.harvesterClusterId;
      this.siteCache = { ...this.siteCache, [credId]: { images: [], networks: [], namespaces: [], loading: true } };
      if (!clusterId) {
        this.siteCache[credId].loading = false;
        return; // ohne Cluster-Id kein Proxy-Pfad → Freitext-Fallback bleibt aktiv
      }
      // try/finally: auch bei unerwartetem Reject nie in loading=true hängen bleiben
      // (CMR-P3) — Fehler degradiert zu leeren Listen = Freitext-Fallback.
      // Parallel: Ceph-Autodiscovery der Site (Kunden geben KEINE Ceph-Interna ein —
      // fsid/Monitore/Pool/cephx kommen komplett von der Site; null = kein Ceph dort).
      try {
        const [res, ceph] = await Promise.all([
          listHarvesterSiteResources(this.$store, clusterId),
          discoverZoneCeph(this.$store, clusterId),
        ]);
        this.siteCache = { ...this.siteCache, [credId]: { ...res, ceph, loading: false } };
      } catch (err) {
        this.siteCache = { ...this.siteCache, [credId]: { images: [], networks: [], namespaces: [], ceph: null, loading: false } };
      }
      this.ensureWorkloadZones();
    },
    // Provider-Wechsel: Credential UND ALLE provider-/site-spezifischen Felder aus frischen
    // Defaults setzen, sonst wandert Alt-Zustand in den neuen Provider (CMR-P3, Phase 1).
    // Sizing/Rollen (cpu/mem/disk/cp/worker/etcdOnly) bleiben erhalten.
    onProviderChange(z) {
      const d = defaultZone(z.zone, z.provider);
      z.credentialId = '';
      z.sshUser      = d.sshUser;
      z.vmNamespace  = d.vmNamespace;
      z.networkName  = d.networkName;
      z.image        = d.image;
      z.nodeStorage  = d.nodeStorage;
      z.cephImage    = d.cephImage;
      z.enableEfi    = d.enableEfi;
      z.vsphere      = { ...d.vsphere };
      this.ensureWorkloadZones();
    },
    addZone() {
      this.spec.zones.push(defaultZone(`z${ this.spec.zones.length + 1 }`));
      this.ensureWorkloadZones();
    },
    removeZone(i) {
      this.spec.zones.splice(i, 1);
      this.ensureWorkloadZones();
    },
    // DNS-Eingabe (CSV) → VsphereSpec.dns string[] (getrimmt, Leere raus).
    setVsphereDns(z, value) {
      z.vsphere.dns = `${ value }`.split(',').map((s) => s.trim()).filter(Boolean);
    },
    // ---- Workload-Ceph (Gast-Storage) ----
    toggleWorkloadCeph(on) {
      this.spec.workloadCeph = on
        ? { clusterID: '', monitors: [], zones: {} }
        : null;
      this.ensureWorkloadZones();
    },
    // Zonen, die Workload-Storage bekommen DÜRFEN: Harvester + nicht etcd-only.
    // Witness-Zonen (HAN) tauchen hier NIE auf — PVCs sind dort by design unmöglich.
    workloadEligibleZones() {
      return this.spec.zones.filter((z) => (z.provider || 'harvester') === 'harvester' && !z.etcdOnly && z.zone);
    },
    // Workload-Zonen-Map EXPLIZIT mit dem Eligible-Set synchronisieren — befüllt
    // AUSSCHLIESSLICH aus der Site-Autodiscovery (Kunde gibt nichts ein). Zonen ohne
    // erkanntes Ceph bekommen KEINEN Eintrag → Invariante blockiert mit klarer Meldung.
    // clusterID/Monitore werden vom ersten erkannten Standort übernommen (gestreckter
    // Ceph = identisch; Abweichung meldet checkCephConsistency als Fehler).
    ensureWorkloadZones() {
      const wc = this.spec.workloadCeph;
      if (!wc) {
        return;
      }
      const zones = {};
      let clusterID = '';
      let monitors = [];
      for (const z of this.workloadEligibleZones()) {
        const ceph = this.siteFor(z).ceph;
        if (!ceph) {
          continue;
        }
        zones[z.zone] = { pool: ceph.pool, userID: ceph.userID, userKey: ceph.userKey };
        if (!clusterID) {
          clusterID = ceph.clusterID;
          monitors = [...ceph.monitors];
        }
      }
      wc.zones = zones;
      wc.clusterID = clusterID;
      wc.monitors = monitors;
    },
    // Discovery-Status einer Zone für die Anzeige (und Konsistenz-Fehler).
    zoneCephStatus(z) {
      const site = this.siteFor(z);
      if (!z.credentialId) {
        return { state: 'no-cred', text: 'Zugang wählen — Storage wird automatisch erkannt' };
      }
      if (site.loading) {
        return { state: 'loading', text: 'erkenne Storage …' };
      }
      if (!site.ceph) {
        return { state: 'missing', text: 'kein zonaler Storage an diesem Standort verfügbar' };
      }
      return { state: 'ok', text: `erkannt — Pool ${ site.ceph.pool }` };
    },
    checkCephConsistency() {
      const wc = this.spec.workloadCeph;
      if (!wc) {
        return [];
      }
      const errs = [];
      for (const z of this.workloadEligibleZones()) {
        const ceph = this.siteFor(z).ceph;
        if (!ceph) {
          errs.push(`Workload-Storage: Standort '${ z.zone }' hat keinen erkennbaren zonalen Storage — Zugang prüfen oder Storage deaktivieren.`);
        } else if (wc.clusterID && ceph.clusterID !== wc.clusterID) {
          errs.push(`Workload-Storage: Standort '${ z.zone }' gehört zu einem anderen Storage-Cluster (${ ceph.clusterID }) als die übrigen (${ wc.clusterID }).`);
        }
      }
      return errs;
    },
    onEtcdOnlyChange() {
      this.ensureWorkloadZones();
    },
    // ---- Aktionen ----
    validateNow() {
      this.ensureWorkloadZones(); // deckt auch Zone-Key-Umbenennungen ab
      this.errors = [...this.checkCephConsistency(), ...validate(this.spec)];
      return this.errors.length === 0;
    },
    push(m) {
      this.log.push(m);
    },
    previewManifest() {
      if (!this.validateNow()) {
        return;
      }
      const { machineConfigs, cluster } = render(this.spec);
      // cephx-Keys aus der ANZEIGE redakten (CMR-P2: die Vorschau ist auch für
      // Nicht-Admins sichtbar; mit Autodiscovery stünde sonst ein echtes Secret im
      // Log-Panel). VOR dem stringify im YAML-String ersetzen — nach dem stringify
      // wäre das Quote JSON-escaped (\") und ein "…"-Regex griffe nicht.
      // Der Create-Pfad nutzt weiterhin das unredaktierte Objekt.
      const safeCluster = JSON.parse(JSON.stringify(cluster));
      const am = safeCluster?.spec?.rkeConfig?.additionalManifest;
      if (typeof am === 'string') {
        safeCluster.spec.rkeConfig.additionalManifest = am.replace(/userKey: ".*"/g, 'userKey: "«redacted»"');
      }
      this.log = [
        '# Hinweis: Secrets (cephx userKey) sind in dieser Vorschau redaktiert.',
        JSON.stringify({ machineConfigs, cluster: safeCluster }, null, 2),
      ];
    },
    async createCluster() {
      if (!this.isAdmin) {
        this.errors = ['Nur Platform-Admins dürfen Multi-Site-Cluster provisionieren.'];
        return;
      }
      if (!this.validateNow()) {
        return;
      }
      this.busy = true;
      this.log = [];
      try {
        const { machineConfigs, cluster } = render(this.spec);
        for (const mc of machineConfigs) {
          // postMachineConfig upsertet (POST, bei 409 PUT) -> keine stale Config.
          this.push(`Upsert ${ mc.kind } ${ mc.metadata.name } ...`);
          await postMachineConfig(this.$store, mc);
        }
        this.push(`POST Cluster ${ cluster.metadata.name } ...`);
        await postCluster(this.$store, cluster);
        this.push('Cluster-Provisioning angestoßen. Warte auf status.ready ...');
        for (let i = 0; i < 90; i++) {
          await new Promise((r) => setTimeout(r, 10000));
          const s = await getClusterStatus(this.$store, cluster.metadata.name);
          this.push(`  [${ i }] ready=${ s.ready }`);
          if (s.ready) {
            this.push('Cluster ist Ready ✅');
            break;
          }
        }
      } catch (e) {
        this.errors = [`Fehler: ${ e?.message || e }`];
      } finally {
        this.busy = false;
      }
    },
  },
};
</script>

<template>
  <div class="msp">
    <header class="msp__header">
      <h1>Multi-Site Cluster Provisioner</h1>
      <p>
        Hochverfügbare Kubernetes-Cluster über mehrere Standorte — mit automatischem
        Failover und optional zonalem Storage für Ihre Anwendungen.
      </p>
    </header>

    <div
      v-if="!isAdmin"
      class="msp__notice"
    >
      Nur <strong>Platform-Admins</strong> können hier provisionieren. Vorschau/Manifest sind sichtbar, „Cluster anlegen" ist deaktiviert.
    </div>

    <div
      v-if="errors.length"
      class="msp__errors"
      role="alert"
    >
      <strong>Bitte korrigieren:</strong>
      <ul>
        <li
          v-for="(err, i) in errors"
          :key="i"
        >
          {{ err }}
        </li>
      </ul>
    </div>

    <!-- ═══ Cluster-Basis ═══ -->
    <section
      class="msp__card"
      aria-label="Cluster-Basis"
    >
      <h2 class="msp__card-title">
        Cluster
      </h2>
      <div class="msp__grid msp__grid--cluster">
        <label>Cluster-Name
          <input v-model="spec.name">
        </label>
        <label>Kubernetes-Version
          <!-- datalist = Dropdown UND Freitext in einem (a11y-nativ); Quelle: Rancher-
               Release-Channel. Leere Liste (API-Fehler) degradiert zu reinem Freitext. -->
          <input
            v-model="spec.k8sVersion"
            list="msp-k8s-versions"
          >
          <datalist id="msp-k8s-versions">
            <option
              v-for="v in k8sVersions"
              :key="v"
              :value="v"
            />
          </datalist>
        </label>
        <label>Pod-CIDR
          <input v-model="spec.podCidr">
        </label>
        <label>Service-CIDR
          <input v-model="spec.serviceCidr">
        </label>
        <label>Routing
          <select v-model="spec.routingMode">
            <option value="tunnel">tunnel (PoC)</option>
            <option value="native">native+BGP (PROD)</option>
          </select>
        </label>
      </div>
    </section>

    <!-- ═══ Zonen ═══ -->
    <div class="msp__zones-head">
      <h2>Standorte <span class="msp__muted">(Zonen)</span></h2>
      <button
        class="msp__btn"
        type="button"
        @click="addZone"
      >
        + Zone
      </button>
    </div>

    <div class="msp__zone-grid">
      <section
        v-for="(z, i) in spec.zones"
        :key="i"
        class="msp__card msp__zone"
        :aria-label="`Zone ${z.zone}`"
      >
        <div class="msp__zone-head">
          <!-- Zone-Rename synct die Workload-Ceph-Map sofort (ehrliches WYSIWYG statt
               stilles Löschen erst beim Validate; Rename = Neuanlage, CMR-R2-P3). -->
          <label class="msp__zone-key">Zone
            <input
              v-model="z.zone"
              maxlength="12"
              @input="ensureWorkloadZones()"
            >
          </label>
          <label>Provider
            <select
              v-model="z.provider"
              @change="onProviderChange(z)"
            >
              <option value="harvester">Harvester</option>
              <option value="vsphere">vSphere</option>
            </select>
          </label>
          <label
            class="msp__check"
            title="Witness/Tiebreaker: reiner etcd-Voter, automatisch getaintet — keine Workloads, kein Storage"
          >
            <input
              v-model="z.etcdOnly"
              type="checkbox"
              @change="onEtcdOnlyChange(z)"
            >
            etcd-only (Witness)
          </label>
          <button
            class="msp__btn msp__btn--ghost msp__zone-remove"
            type="button"
            :aria-label="`Zone ${z.zone} entfernen`"
            @click="removeZone(i)"
          >
            ✕
          </button>
        </div>

        <fieldset class="msp__fieldset">
          <legend>Zugang</legend>
          <div class="msp__grid">
            <label>Cloud-Credential
              <select
                v-model="z.credentialId"
                :disabled="loadingCreds"
                @change="onCredentialChange(z)"
              >
                <option value="">— wählen —</option>
                <option
                  v-for="c in credsForProvider(z.provider)"
                  :key="c.id"
                  :value="c.id"
                >
                  {{ c.name }} ({{ c.id }})
                </option>
              </select>
            </label>
            <label title="Cloud-Image-User: SLE/Leap Micro=sles, Ubuntu=ubuntu">sshUser
              <input v-model="z.sshUser">
            </label>
          </div>
        </fieldset>

        <fieldset class="msp__fieldset">
          <legend>Compute</legend>
          <div class="msp__grid msp__grid--compute">
            <label>vCPU
              <input
                v-model.number="z.cpu"
                type="number"
                min="1"
              >
            </label>
            <label>RAM (GiB)
              <input
                v-model.number="z.mem"
                type="number"
                min="1"
              >
            </label>
            <label>Disk (GiB)
              <input
                v-model.number="z.disk"
                type="number"
                min="10"
              >
            </label>
            <label
              title="etcd+controlplane Nodes"
              :class="{ 'msp__disabled': z.etcdOnly }"
            >CP
              <input
                v-model.number="z.cpQuantity"
                type="number"
                min="0"
                :disabled="z.etcdOnly"
              >
            </label>
            <label :class="{ 'msp__disabled': z.etcdOnly }">Worker
              <input
                v-model.number="z.workerCount"
                type="number"
                min="0"
                :disabled="z.etcdOnly"
              >
            </label>
          </div>
        </fieldset>

        <!-- Harvester-Details -->
        <fieldset
          v-if="z.provider !== 'vsphere'"
          class="msp__fieldset"
          :aria-busy="siteFor(z).loading"
        >
          <legend>
            Standort-Details
            <span
              v-if="siteFor(z).loading"
              class="msp__muted"
            > — lade Standort-Ressourcen…</span>
          </legend>
          <p
            v-if="!z.credentialId"
            class="msp__hint"
          >
            Zuerst oben ein <strong>Cloud-Credential</strong> wählen — Namespaces, Netzwerke
            und Images werden dann automatisch vom Standort geladen.
          </p>
          <div class="msp__grid">
            <label>VM-Namespace
              <select
                v-if="siteFor(z).namespaces.length"
                v-model="z.vmNamespace"
              >
                <option
                  v-for="ns in siteFor(z).namespaces"
                  :key="ns"
                  :value="ns"
                >
                  {{ ns }}
                </option>
              </select>
              <input
                v-else
                v-model="z.vmNamespace"
              >
            </label>
            <label>VM-Netzwerk (NAD)
              <select
                v-if="siteFor(z).networks.length"
                v-model="z.networkName"
              >
                <option
                  v-for="n in siteFor(z).networks"
                  :key="n"
                  :value="n"
                >
                  {{ n }}
                </option>
              </select>
              <input
                v-else
                v-model="z.networkName"
                placeholder="ns/nad-name"
              >
            </label>
            <label title="Node-Root-Storage der Site: Longhorn (Default) oder Ceph — Root-PVC landet auf Rook-Ceph-RBD (VMImage mit backend=cdi + targetStorageClassName)">Node-Storage
              <select v-model="z.nodeStorage">
                <option value="longhorn">Longhorn</option>
                <option value="ceph">Ceph (Rook-RBD)</option>
              </select>
            </label>
            <label v-if="z.nodeStorage !== 'ceph'">Root-Image
              <select
                v-if="siteFor(z).images.length"
                v-model="z.image"
              >
                <option value="">— wählen —</option>
                <option
                  v-for="img in siteFor(z).images"
                  :key="img.id"
                  :value="img.id"
                >
                  {{ img.label }} ({{ img.id }})
                </option>
              </select>
              <input
                v-else
                v-model="z.image"
                placeholder="default/image-…"
              >
            </label>
            <label
              v-else
              title="Ceph-VMImage der Site (backend=cdi): spec.targetStorageClassName zeigt auf rook-ceph-…-rbd — nur dann landet die Root-PVC auf Ceph"
            >Ceph-Image
              <select
                v-if="siteFor(z).images.length"
                v-model="z.cephImage"
              >
                <option value="">— wählen —</option>
                <option
                  v-for="img in siteFor(z).images"
                  :key="img.id"
                  :value="img.id"
                >
                  {{ img.label }}{{ img.targetSc ? ` → ${img.targetSc}` : '' }} ({{ img.id }})
                </option>
              </select>
              <input
                v-else
                v-model="z.cephImage"
                placeholder="default/ceph-node-image"
              >
            </label>
            <label
              class="msp__check"
              title="EFI-Boot — image-/insel-abhängig"
            >
              <input
                v-model="z.enableEfi"
                type="checkbox"
              >
              EFI
            </label>
          </div>
        </fieldset>

        <!-- vSphere-Details -->
        <template v-else>
          <fieldset
            class="msp__fieldset"
            :aria-busy="vsFor(z).loading || vsDcFor(z).loading"
          >
            <legend>vSphere-Platzierung</legend>
            <!-- Dropdowns aus dem vCenter-Inventar (/meta/vsphere, wie Ranchers eigener
                 vSphere-Wizard); leere Liste = Freitext-Fallback (fail-open). Datastore-
                 abhängige Listen laden nach Datacenter-Wahl. -->
            <p
              v-if="!z.credentialId"
              class="msp__hint"
            >
              Zuerst oben ein <strong>Cloud-Credential</strong> wählen — Datacenter, Datastores,
              Netzwerke und Templates werden dann automatisch vom vCenter geladen.
            </p>
            <div class="msp__grid">
              <label>Datacenter
                <select
                  v-if="vsFor(z).dataCenters.length"
                  v-model="z.vsphere.datacenter"
                  @change="onVsphereDatacenterChange(z)"
                >
                  <option value="">— wählen —</option>
                  <option
                    v-if="z.vsphere.datacenter && !vsFor(z).dataCenters.includes(z.vsphere.datacenter)"
                    :value="z.vsphere.datacenter"
                  >
                    {{ z.vsphere.datacenter }} (manuell)
                  </option>
                  <option
                    v-for="dc in vsFor(z).dataCenters"
                    :key="dc"
                    :value="dc"
                  >
                    {{ dc }}
                  </option>
                </select>
                <input
                  v-else
                  v-model="z.vsphere.datacenter"
                  placeholder="HAN-DC01"
                  @change="onVsphereDatacenterChange(z)"
                >
              </label>
              <label>Datastore
                <select
                  v-if="vsDcFor(z).dataStores.length"
                  v-model="z.vsphere.datastore"
                >
                  <option value="">—</option>
                  <option
                    v-if="z.vsphere.datastore && !vsDcFor(z).dataStores.includes(z.vsphere.datastore)"
                    :value="z.vsphere.datastore"
                  >
                    {{ z.vsphere.datastore }} (manuell)
                  </option>
                  <option
                    v-for="o in vsDcFor(z).dataStores"
                    :key="o"
                    :value="o"
                  >
                    {{ o }}
                  </option>
                </select>
                <input
                  v-else
                  v-model="z.vsphere.datastore"
                >
              </label>
              <label title="Storage-DRS-Cluster — alternativ zu Datastore (genau eines; datastoreCluster hat Vorrang)">Datastore-Cluster
                <select
                  v-if="vsDcFor(z).dataStoreClusters.length"
                  v-model="z.vsphere.datastoreCluster"
                >
                  <option value="">—</option>
                  <option
                    v-if="z.vsphere.datastoreCluster && !vsDcFor(z).dataStoreClusters.includes(z.vsphere.datastoreCluster)"
                    :value="z.vsphere.datastoreCluster"
                  >
                    {{ z.vsphere.datastoreCluster }} (manuell)
                  </option>
                  <option
                    v-for="o in vsDcFor(z).dataStoreClusters"
                    :key="o"
                    :value="o"
                  >
                    {{ o }}
                  </option>
                </select>
                <input
                  v-else
                  v-model="z.vsphere.datastoreCluster"
                >
              </label>
              <label>Resource-Pool
                <select
                  v-if="vsDcFor(z).pools.length"
                  v-model="z.vsphere.pool"
                >
                  <option value="">—</option>
                  <option
                    v-if="z.vsphere.pool && !vsDcFor(z).pools.includes(z.vsphere.pool)"
                    :value="z.vsphere.pool"
                  >
                    {{ z.vsphere.pool }} (manuell)
                  </option>
                  <option
                    v-for="o in vsDcFor(z).pools"
                    :key="o"
                    :value="o"
                  >
                    {{ o }}
                  </option>
                </select>
                <input
                  v-else
                  v-model="z.vsphere.pool"
                >
              </label>
              <label>VM-Folder
                <select
                  v-if="vsDcFor(z).folders.length"
                  v-model="z.vsphere.folder"
                >
                  <option value="">—</option>
                  <option
                    v-if="z.vsphere.folder && !vsDcFor(z).folders.includes(z.vsphere.folder)"
                    :value="z.vsphere.folder"
                  >
                    {{ z.vsphere.folder }} (manuell)
                  </option>
                  <option
                    v-for="o in vsDcFor(z).folders"
                    :key="o"
                    :value="o"
                  >
                    {{ o }}
                  </option>
                </select>
                <input
                  v-else
                  v-model="z.vsphere.folder"
                >
              </label>
              <label title="Bindung per MOID (eindeutig bei gleichnamigen PortGroups); Freitext-Name bleibt gültig">Network (PortGroup)
                <select
                  v-if="vsDcFor(z).networks.length"
                  v-model="z.vsphere.network"
                >
                  <option value="">— wählen —</option>
                  <option
                    v-if="z.vsphere.network && !vsDcFor(z).networks.some((o) => o.value === z.vsphere.network)"
                    :value="z.vsphere.network"
                  >
                    {{ z.vsphere.network }} (manuell)
                  </option>
                  <option
                    v-for="o in vsDcFor(z).networks"
                    :key="o.value"
                    :value="o.value"
                  >
                    {{ o.label }}
                  </option>
                </select>
                <input
                  v-else
                  v-model="z.vsphere.network"
                >
              </label>
              <label>Template (cloneFrom)
                <select
                  v-if="vsDcFor(z).templates.length"
                  v-model="z.vsphere.cloneFrom"
                >
                  <option value="">— wählen —</option>
                  <option
                    v-if="z.vsphere.cloneFrom && !vsDcFor(z).templates.includes(z.vsphere.cloneFrom)"
                    :value="z.vsphere.cloneFrom"
                  >
                    {{ z.vsphere.cloneFrom }} (manuell)
                  </option>
                  <option
                    v-for="o in vsDcFor(z).templates"
                    :key="o"
                    :value="o"
                  >
                    {{ o }}
                  </option>
                </select>
                <input
                  v-else
                  v-model="z.vsphere.cloneFrom"
                >
              </label>
              <label>OS <input v-model="z.vsphere.os"></label>
            </div>
          </fieldset>
          <fieldset class="msp__fieldset">
            <legend>Static-IP <span class="msp__muted">(nur Segmente ohne DHCP — leer = DHCP)</span></legend>
            <div class="msp__grid">
              <label title="Statische IPv4 via cloud-init/guestinfo.metadata; erlaubt genau 1 Node in der Zone">IP
                <input
                  v-model="z.vsphere.staticIp"
                  placeholder="10.10.54.10"
                >
              </label>
              <label>/Prefix
                <input
                  v-model.number="z.vsphere.prefix"
                  type="number"
                  min="1"
                  max="32"
                >
              </label>
              <label title="Pflicht bei Static-IP — etcd-Peers der anderen Sites sind L3-geroutet">Gateway
                <input
                  v-model="z.vsphere.gateway"
                  placeholder="10.10.54.1"
                >
              </label>
              <label title="Nameserver, kommasepariert">DNS
                <input
                  :value="(z.vsphere.dns || []).join(',')"
                  placeholder="10.10.0.53,10.10.0.54"
                  @input="setVsphereDns(z, $event.target.value)"
                >
              </label>
            </div>
          </fieldset>
        </template>
      </section>
    </div>

    <!-- ═══ Workload-Storage (optional) ═══ -->
    <section
      class="msp__card"
      aria-label="Workload-Storage"
    >
      <div class="msp__zones-head msp__zones-head--tight">
        <h2 class="msp__card-title">
          Workload-Storage <span class="msp__muted">(Kunden-PVCs, zonal)</span>
        </h2>
        <label class="msp__check">
          <input
            type="checkbox"
            :checked="!!spec.workloadCeph"
            @change="toggleWorkloadCeph($event.target.checked)"
          >
          Ceph aktivieren
        </label>
      </div>
      <template v-if="spec.workloadCeph">
        <p class="msp__hint">
          Stellt Ihren Anwendungen replizierten Block-Storage bereit — je Standort eine
          StorageClass <code>ceph-rbd-&lt;standort&gt;</code>, Volumes bleiben strikt in ihrem
          Standort. Witness-Standorte erhalten grundsätzlich keinen Storage. Alle
          Verbindungsdaten werden automatisch vom jeweiligen Standort ermittelt.
        </p>
        <div
          v-for="z in workloadEligibleZones()"
          :key="z.zone"
          class="msp__wc-zone"
        >
          <span class="msp__wc-zone-badge">{{ z.zone }}</span>
          <span
            class="msp__wc-status"
            :class="`msp__wc-status--${zoneCephStatus(z).state}`"
          >
            {{ zoneCephStatus(z).text }}
          </span>
        </div>
      </template>
    </section>

    <div class="msp__actions">
      <button
        class="msp__btn"
        type="button"
        :disabled="busy"
        @click="previewManifest"
      >
        Manifest-Vorschau
      </button>
      <button
        class="msp__btn msp__btn--primary"
        type="button"
        :disabled="busy || !isAdmin"
        @click="createCluster"
      >
        {{ busy ? 'Provisioniere …' : 'Cluster anlegen' }}
      </button>
    </div>

    <pre
      v-if="log.length"
      class="msp__log"
    >{{ log.join('\n') }}</pre>
  </div>
</template>

<style lang="scss" scoped>
