import { ClusterSpec } from './renderManifest';

// Strikte IPv4-Prüfung: 4 Oktette 0–255, KEINE führenden Nullen (CMR-P3 —
// '010.0.0.1' wäre bei netplan/cloud-init-Parsern ambig, oktal vs dezimal).
function isIpv4(s: string): boolean {
  const parts = s.split('.');
  if (parts.length !== 4) {
    return false;
  }
  return parts.every((p) => /^(0|[1-9]\d{0,2})$/.test(p) && Number(p) <= 255);
}

// Harte S22-Invarianten. Jede Verletzung blockiert den Create-Flow.
// (Im Kunden-Modus zusätzlich server-seitig erzwingen — Defense-in-Depth.)
export function validate(spec: ClusterSpec): string[] {
  const e: string[] = [];

  if (!/^[a-z0-9-]{1,40}$/.test(spec.name || '')) {
    e.push('Cluster-Name: nur a-z 0-9 - , max 40 Zeichen.');
  }
  if (!spec.k8sVersion) {
    e.push('Kubernetes-Version fehlt.');
  }
  if (!['native', 'tunnel'].includes(spec.routingMode)) {
    e.push('routingMode muss native oder tunnel sein.');
  }

  const zones = spec.zones || [];
  if (zones.length < 2) {
    e.push('Mindestens 2 Zonen (z.B. b1, b2) erforderlich.');
  }

  // Zone-Keys müssen EINDEUTIG sein — sonst kollidieren HarvesterConfig- und
  // machine-pool-Namen (Rancher keyed by name) -> reconcile-Konflikt/Reject.
  const zoneKeys = zones.map((z) => z.zone).filter(Boolean);
  if (new Set(zoneKeys).size !== zoneKeys.length) {
    e.push('Zone-Keys müssen eindeutig sein (doppelte b1/b2/… kollidieren bei Pool-/Config-Namen).');
  }
  // Zone-Keys fließen in K8s-NAMEN (Pools, Configs, Secrets, StorageClasses, Labels) —
  // strikt DNS-safe halten (CMR-P2: verhindert zugleich YAML-/Namens-Injection).
  for (const zk of zoneKeys) {
    // DNS-Label-Regel: alnum an Start/Ende, '-' nur innen (CMR-R2-P3).
    if (!/^[a-z0-9](?:[a-z0-9-]{0,10}[a-z0-9])?$/.test(zk)) {
      e.push(`Zone-Key '${zk}': a-z 0-9, '-' nur innen, max 12 Zeichen (DNS-Label).`);
    }
  }

  // per-Pool-Credential: jede Zone braucht ein Credential, und sie müssen
  // UNTERSCHIEDLICH sein (= verschiedene Harvester-Inseln). Das ist der Kern.
  const creds = zones.map((z) => z.credentialId).filter(Boolean);
  if (creds.length !== zones.length) {
    e.push('Jede Zone braucht ein eigenes Cloud-Credential (per-Pool).');
  }
  if (new Set(creds).size !== creds.length) {
    e.push('Pro Zone ein UNTERSCHIEDLICHES Credential (verschiedene Harvester-Inseln).');
  }

  // etcd-Quorum: ungerade Member-Zahl, mindestens 3.
  let etcdNodes = 0;
  for (const z of zones) {
    if (!z.zone) {
      e.push('Jede Zone braucht einen Zone-Key (b1/b2/han).');
    }
    // Provider-abhängige Pflichtfelder (Default harvester).
    if ((z.provider || 'harvester') === 'vsphere') {
      const v = z.vsphere;
      if (!v || !v.datacenter) {
        e.push(`Zone ${z.zone || '?'} (vSphere): datacenter fehlt.`);
      }
      if (!v || !v.network) {
        e.push(`Zone ${z.zone || '?'} (vSphere): network (PortGroup) fehlt.`);
      }
      if (!v || !v.cloneFrom) {
        e.push(`Zone ${z.zone || '?'} (vSphere): cloneFrom (Template-VM) fehlt.`);
      }
      // Genau ein Storage-Ziel nötig — sonst kann der vSphere-Driver die VM nicht platzieren.
      if (!v || (!v.datastore && !v.datastoreCluster)) {
        e.push(`Zone ${z.zone || '?'} (vSphere): datastore oder datastoreCluster fehlt.`);
      }
      // Static-IP (Segment ohne DHCP): ohne gültige IP+Gateway hängt der Driver in
      // „waiting for IP" bzw. der etcd-Peer ist nicht L3-erreichbar.
      if (v?.staticIp?.trim()) {
        const ip = v.staticIp.trim();
        if (!isIpv4(ip)) {
          e.push(`Zone ${z.zone || '?'} (vSphere): staticIp '${ip}' ist keine gültige IPv4.`);
        }
        if (!v.gateway?.trim()) {
          e.push(`Zone ${z.zone || '?'} (vSphere): gateway ist Pflicht bei staticIp (etcd-Peers sind L3-geroutet).`);
        } else if (!isIpv4(v.gateway.trim())) {
          e.push(`Zone ${z.zone || '?'} (vSphere): gateway '${v.gateway.trim()}' ist keine gültige IPv4.`);
        }
        if (v.prefix != null && (!Number.isInteger(v.prefix) || v.prefix < 1 || v.prefix > 32)) {
          e.push(`Zone ${z.zone || '?'} (vSphere): prefix muss 1–32 sein (aktuell ${v.prefix}).`);
        }
        for (const d of v.dns || []) {
          if (d.trim() && !isIpv4(d.trim())) {
            e.push(`Zone ${z.zone || '?'} (vSphere): DNS '${d.trim()}' ist keine gültige IPv4.`);
          }
        }
        // Die MachineConfig (inkl. der EINEN statischen IP) gilt für ALLE Nodes der Zone —
        // mehr als 1 Node = IP-Konflikt. Witness ist ohnehin etcdOnly (genau 1 Voter).
        const nodeCount = z.etcdOnly ? 1 : (z.cpQuantity || 0) + (z.workerCount || 0);
        if (nodeCount !== 1) {
          e.push(`Zone ${z.zone || '?'} (vSphere): staticIp erlaubt genau 1 Node in der Zone (aktuell ${nodeCount}) — die IP gilt pro MachineConfig.`);
        }
      }
    } else {
      // Root-Storage: 'ceph' verlangt eine Ceph-VMImage der Site (Invariante „ceph nur
      // wenn die Site ein Ceph-Image hat"), sonst das Longhorn-image. Nur eines zählt.
      // Getrimmt geprüft, damit reiner Whitespace nicht als „gesetzt" durchrutscht (CMR-P2).
      if (z.nodeStorage === 'ceph') {
        if (!z.cephImage?.trim()) {
          e.push(`Zone ${z.zone || '?'} (Harvester/Ceph): cephImage fehlt — die Site braucht eine Ceph-VMImage (spec.targetStorageClassName=rook-ceph…-rbd).`);
        }
      } else if (!z.image?.trim()) {
        e.push(`Zone ${z.zone || '?'} (Harvester): Image fehlt.`);
      }
      if (!z.networkName) {
        e.push(`Zone ${z.zone || '?'} (Harvester): networkName fehlt.`);
      }
    }
    etcdNodes += z.etcdOnly ? 1 : z.cpQuantity;
  }
  if (etcdNodes < 3) {
    e.push(`etcd: mindestens 3 Member über die Zonen (aktuell ${etcdNodes}).`);
  }
  if (etcdNodes % 2 === 0) {
    e.push(`etcd: ungerade Member-Zahl für sauberes Quorum (aktuell ${etcdNodes}).`);
  }

  // Mind. EIN Control-Plane-Pool — sonst bootet RKE2 nicht (etcd-only reicht nicht).
  if (!zones.some((z) => !z.etcdOnly && z.cpQuantity > 0)) {
    e.push('Mindestens eine Zone mit Control-Plane-Nodes (cpQuantity ≥ 1, nicht etcd-only).');
  }
  // Mind. EIN Worker — CP ist dediziert (workerRole:false), sonst keine Workload-Kapazität.
  if (!zones.some((z) => !z.etcdOnly && z.workerCount > 0)) {
    e.push('Mindestens eine Zone mit Worker-Nodes (workerCount ≥ 1).');
  }

  // Workload-Ceph (optionales Gast-Storage): PVCs strikt zonal, NIE auf Witness-Zonen.
  const wc = spec.workloadCeph;
  if (wc) {
    if (!wc.clusterID?.trim()) {
      e.push('Workload-Ceph: clusterID (Ceph fsid) fehlt.');
    }
    // Jeder ORIGINAL-Eintrag muss valide sein (leer/Whitespace = Fehler, kein stilles
    // Wegfiltern) + Port numerisch 1–65535 (CMR-P3). Der Renderer nutzt dieselbe
    // Normalisierung (trim), es kann also nichts Ungeprüftes ins Manifest gelangen.
    const monsRaw = wc.monitors || [];
    if (monsRaw.length < 1) {
      e.push('Workload-Ceph: mindestens ein Monitor (host:port) erforderlich.');
    }
    for (const m0 of monsRaw) {
      const m = `${m0 ?? ''}`.trim();
      const match = /^([a-zA-Z0-9._-]+):(\d{1,5})$/.exec(m);
      const port = match ? Number(match[2]) : 0;
      if (!match || port < 1 || port > 65535) {
        e.push(`Workload-Ceph: Monitor '${m0}' ist kein gültiges host:port (Port 1–65535).`);
      }
    }
    // EXAKTES Eligible-Set (CMR-P2): JEDE Harvester-Zone ohne etcd-only braucht einen
    // Eintrag (sonst hätte eine BER-Zone still kein Kunden-Storage), und es darf KEINE
    // Extras geben (vSphere/etcd-only/unbekannt) — Witness-Zonen (HAN) sind damit
    // wasserdicht ausgeschlossen.
    const eligible = zones
      .filter((z) => (z.provider || 'harvester') === 'harvester' && !z.etcdOnly && z.zone)
      .map((z) => z.zone);
    const configured = Object.keys(wc.zones || {});
    for (const zn of eligible) {
      if (!configured.includes(zn)) {
        e.push(`Workload-Ceph: Zone '${zn}' fehlt — jede Harvester-Zone (nicht etcd-only) braucht pool/userID/userKey.`);
      }
    }
    for (const zn of configured) {
      if (!eligible.includes(zn)) {
        e.push(`Workload-Ceph: Zone '${zn}' ist nicht zulässig (nur Harvester-Zonen ohne etcd-only — Witness/HAN bekommt NIEMALS Storage).`);
      }
    }
    for (const [zn, zc] of Object.entries(wc.zones || {})) {
      if (!zc.pool?.trim()) e.push(`Workload-Ceph Zone '${zn}': pool fehlt.`);
      if (!zc.userID?.trim()) e.push(`Workload-Ceph Zone '${zn}': userID fehlt.`);
      if (!zc.userKey?.trim()) e.push(`Workload-Ceph Zone '${zn}': userKey fehlt.`);
    }
  }

  return e;
}
