// Entscheidet über die Erlaubnis (Admin/Entitlement) — für die AKTION, nicht die Nav.
//
// HEUTE: Platform-Admins. Die isAdminUser-Logik ist hier LOKAL nachgebildet und NICHT
// aus @shell/store/type-map importiert — dieser Import zog das ganze Modul + seinen
// dynamischen Importer in den Extension-Bundle (811 KiB statt ~29 KiB, CMR-P2). Admin =
// darf PUT auf die zentralen Management-/Catalog-Schemas (RBAC-/Schema-basiert, exakt
// wie Rancher's isAdminUser).
//
// WICHTIG: Das Produkt wird in product.ts BEDINGUNGSLOS registriert. Die Nav NICHT an
// async Admin-/Schema-State koppeln — init() läuft einmalig beim Plugin-Load, bevor
// management-Schemas da sind → sonst fail-closed und für ALLE (auch Admins) unsichtbar.
// Admin-only ist deshalb auf die Wizard-Aktion gezogen, wo dieser Check zur Nav-Zeit greift.
//
// SPÄTER (Kunden-Publish): entitlement-gated + per-Tenant — nur diese Funktion umstellen.
const ADMIN_SCHEMAS = [
  'management.cattle.io.setting',
  'management.cattle.io.feature',
  'catalog.cattle.io.app',
  'catalog.cattle.io.clusterrepo',
  'catalog.cattle.io.operation',
];

export function isAllowed(store: any): boolean {
  try {
    return ADMIN_SCHEMAS.every((type) =>
      (store.getters['management/schemaFor'](type)?.resourceMethods || []).includes('PUT'));
  } catch (e) {
    return false; // fail-closed
  }
}
