import { importTypes } from '@rancher/auto-import';
import { IPlugin } from '@shell/core/types';
import ProvisionWizard from './components/ProvisionWizard.vue';

export default function (plugin: IPlugin): void {
  importTypes(plugin);

  plugin.metadata = require('./package.json');

  plugin.addProduct(require('./product'));

  plugin.addRoute({
    name:      'multisite-cluster-provisioner',
    path:      '/multisite-cluster-provisioner',
    component: ProvisionWizard,
    meta:      { product: 'multisite-cluster-provisioner' },
  });

  // Cluster-scoped Route (Parität mit cloud-services-marketplace) — damit `to` auch
  // im Cluster-Kontext (/c/:cluster/…) auflöst und nicht ins Leere zeigt.
  plugin.addRoute({
    name:      'c-cluster-multisite-cluster-provisioner',
    path:      '/c/:cluster/multisite-cluster-provisioner',
    component: ProvisionWizard,
    meta:      { product: 'multisite-cluster-provisioner' },
  });
}
