// Rendert die Manifeste für einen gestreckten Multi-Site-RKE2-Cluster.
//
// Erzeugt je Zone EINE MachineConfig (HarvesterConfig ODER VmwarevsphereConfig,
// je nach ZoneSpec.provider) + EINEN provisioning.cattle.io Cluster.
// Kern (warum die Standard-UI das nicht kann):
//   - per-Zone cloudCredentialSecretName  (jede Zone = eigene Site/Insel)
//   - gemischte Provider (Harvester-Inseln B1/B2 + vSphere-Witness, z.B. HAN)
//   - cloud-provider-name bleibt UNGESETZT: der in RKE2 eingebaute Cloud-Controller
//     (hypervisor-agnostisch, keine Site-Bindung) setzt Node-providerID + Adressen.
//     NIE 'external' ohne deployetes CCM — sonst setzt niemand node.spec.providerID,
//     Rancher (machinenodelookup) wartet endlos: keine addresses/join-url, Machines
//     nie Running. RCA: customer-platform docs/reviews/RANCHER_MACHINEPROVISION_RCA_20260702.md
import blueprints from '../data/blueprints.json';

// vSphere/vCenter-spezifische Felder (provider='vsphere', z.B. HAN-Witness-Site).
// Feld-Set aus dem rke-machine-config DynamicSchema `vmwarevsphereconfig` (authoritativ).
export interface VsphereSpec {
  datacenter: string;        // z.B. '/HAN-DC'
  datastore?: string;        // Datastore ODER datastoreCluster (genau eines)
  datastoreCluster?: string;
  pool?: string;             // Resource-Pool
  folder?: string;           // VM-Folder
  network: string;           // PortGroup-Name
  cloneFrom: string;         // Template-VM (SLE-Micro/Ubuntu am Ziel-vCenter)
  hostsystem?: string;
  os?: string;               // Default 'linux'
  // --- Static-IP (Segmente OHNE DHCP, z.B. HAN-Witness LS_FCS_dev-3-etcd-witness) ---
  // Der Rancher-vSphere-Driver wartet auf eine IPv4 via VMware-Tools; ohne DHCP hängt
  // das Provisioning („waiting for IP"). Fix: cloud-init network-config v2 via
  // guestinfo.metadata (cfgparam, base64) — live bewiesen (guestinfo-Datasource aktiv
  // im Leap-Micro-Template, NIC-Driver vmxnet3). userdata bleibt Rancher/CAPR
  // (system-agent) über guestinfo.userdata — KEIN Konflikt, andere guestinfo-Keys.
  staticIp?: string;         // z.B. '10.10.54.10' — leer = DHCP (Default)
  prefix?: number;           // CIDR-Prefix, Default 24
  gateway?: string;          // Pflicht bei staticIp (etcd-Peers sind L3-geroutet)
  dns?: string[];            // Nameserver, z.B. ['10.10.0.53']
}

export interface ZoneSpec {
  zone: string;          // 'b1' | 'b2' | 'han'
  credentialId: string;  // z.B. 'cc-nxbxd' (ohne cattle-global-data: Präfix)
  provider?: 'harvester' | 'vsphere'; // Default 'harvester' (rückwärtskompatibel)
  // --- Harvester (provider='harvester') ---
  vmNamespace?: string;
  networkName?: string;  // z.B. 'shared-k8s/fcs-backend-vm-net'
  image?: string;        // Longhorn-Root-Image, z.B. 'default/image-zrfv4'
  // Node-Root-Storage der Site: 'longhorn' (Default, image) ODER 'ceph' (cephImage).
  // Bei 'ceph' rendert der Harvester-Node NICHT `image`, sondern `cephImage` — eine
  // VMImage, deren `spec.targetStorageClassName` auf die Rook-Ceph-RBD-StorageClass der
  // Site zeigt (dev=rook-ceph-harvester-a-rbd, dev-2=rook-ceph-harvester-b-rbd). Dadurch
  // landet die Root-Disk-PVC auf Ceph (live bewiesen auf v1.8.1, cephroot-test).
  // Rückwärtskompatibel: fehlt das Feld, gilt 'longhorn'.
  nodeStorage?: 'longhorn' | 'ceph';
  cephImage?: string;    // Ceph-Root-Image der Site, z.B. 'default/cephimg-…' (nur bei nodeStorage='ceph')
  // EFI-Boot-Fähigkeit ist image-/insel-abhängig (PoC-Befund: dasselbe Leap-Micro-Image
  // bootete auf dev nur mit enableEfi=false, auf DC2 nur mit true — Root-Cause offen,
  // siehe docs/reviews/SFH_MULTISITE_POC_FINDINGS). Default true, NICHT hart erzwingen.
  enableEfi?: boolean;
  // --- vSphere/vCenter (provider='vsphere', z.B. HAN-Witness) ---
  vsphere?: VsphereSpec;
  // --- gemeinsam ---
  sshUser?: string;      // Cloud-Image-User (SLE Micro=sles, Ubuntu=ubuntu, …); Default 'sles'
  cpu: number;
  mem: number;           // GiB
  disk: number;          // GiB
  cpQuantity: number;    // etcd+controlplane Nodes (0 = keine)
  workerCount: number;   // Worker Nodes (0 = keine)
  etcdOnly?: boolean;    // Tiebreaker/Witness: 1 etcd-Voter, getaintet, kein cp/worker
}

// Kunden-Workload-Storage im Gast (optional): ceph-csi-rbd konsumiert den gestreckten
// Host-Ceph mit ZONALEN StorageClasses (ceph-rbd-<zone>) — PVCs sind damit strikt auf
// die angegebenen (BER-)Zonen beschränkt; Witness-Zonen (etcdOnly) bekommen NIE eine SC,
// kein nodeplugin (kein etcd-Toleration) und kein CSI-Topology-Label (dreifache Garantie,
// live bewiesen stretch-3site 2026-07-02).
export interface WorkloadCephZone {
  pool: string;    // per-Site-RBD-Pool im gestreckten Ceph, z.B. 'harvester-a-rbd'
  userID: string;  // cephx-User (PROD: eigener Least-Privilege-User je Gast-Cluster!)
  userKey: string; // cephx-Key — landet als Secret im Gast; steht im Cluster-Objekt
                   // (additionalManifest) im Klartext → DEV ok, PROD: External Secrets.
}
export interface WorkloadCephSpec {
  clusterID: string;              // Ceph fsid des gestreckten Clusters
  monitors: string[];             // Mon-Endpunkte host:port (aus Gast-Node-Netzen erreichbar!)
  zones: Record<string, WorkloadCephZone>; // key = ZoneSpec.zone (nur nicht-etcdOnly Harvester-Zonen)
}

export interface ClusterSpec {
  name: string;
  k8sVersion: string;
  podCidr: string;
  serviceCidr: string;
  routingMode: 'native' | 'tunnel';
  zones: ZoneSpec[];
  workloadCeph?: WorkloadCephSpec | null; // optional (Default: kein Gast-Storage gerendert)
}

const GD = 'cattle-global-data:';

function harvesterConfig(spec: ClusterSpec, z: ZoneSpec) {
  // Root-Storage-Wahl der Zone: bei 'ceph' die Ceph-VMImage der Site verwenden (deren
  // targetStorageClassName die Root-PVC auf Rook-Ceph-RBD legt), sonst das Longhorn-Image.
  // Default 'longhorn' (rückwärtskompatibel — Alt-Specs ohne nodeStorage bleiben unverändert).
  // getrimmt, damit Rand-Whitespace nicht in einen ungültigen imageName gerät (CMR-P2).
  const rawImage = z.nodeStorage === 'ceph' ? z.cephImage : z.image;
  const rootImage = (rawImage || '').trim();
  return {
    apiVersion: 'rke-machine-config.cattle.io/v1',
    kind:       'HarvesterConfig',
    metadata:   { name: `nc-${spec.name}-${z.zone}`, namespace: 'fleet-default' },
    cpuCount:   String(z.cpu),
    memorySize: String(z.mem),
    diskBus:    'virtio',
    diskInfo:   JSON.stringify({ disks: [{ imageName: rootImage, bootOrder: 1, size: z.disk }] }),
    diskSize:   '0',
    // EFI ist image-/insel-abhängig (s. ZoneSpec.enableEfi) — Default true, aber überschreibbar.
    enableEfi:        z.enableEfi ?? true,
    enableSecureBoot: false,
    enableTpm:        false,
    networkInfo: JSON.stringify({ interfaces: [{ networkName: z.networkName }] }),
    vmNamespace: z.vmNamespace,
    // Muss zum gewählten Cloud-Image passen, sonst scheitert der Rancher-Machine-
    // Bootstrap über SSH (CMR-High): SLE/Leap Micro=sles, Ubuntu=ubuntu, …
    sshUser:     z.sshUser || 'sles',
    userData: [
      '#cloud-config',
      'package_update: true',
      'packages:',
      '  - qemu-guest-agent',
      // SLE-Micro: health-checker.service bildet sonst einen systemd-Zyklus, der
      // cloud-init/Bootstrap blockiert — Fix übernommen aus Referenz prod-01.
      'bootcmd:',
      '  - |',
      '    mkdir -p /etc/systemd/system/health-checker.service.d',
      "    printf '[Unit]\\nAfter=\\n' > /etc/systemd/system/health-checker.service.d/no-cycle.conf",
      '    systemctl daemon-reload',
      '    systemctl start --no-block cloud-final.service || true',
      'runcmd:',
      "  - [systemctl, enable, '--now', qemu-guest-agent.service]",
      '',
    ].join('\n'),
  };
}

// vSphere/vCenter-Node (provider='vsphere') → VmwarevsphereConfig. Feld-Set + Einheiten
// aus dem rke-machine-config DynamicSchema: memorySize/diskSize in MB (Harvester nutzt GiB),
// `network` ist eine Liste (PortGroups), Klon aus einer Template-VM (creationType='template').
// Den RKE2-Bootstrap injiziert Rancher/CAPR selbst per cloud-init; template-spezifische
// Tweaks (z.B. open-vm-tools) gehören ins vCenter-Template, nicht hierher.
function vsphereConfig(spec: ClusterSpec, z: ZoneSpec) {
  const v = z.vsphere as VsphereSpec;
  const cfg: any = {
    apiVersion:   'rke-machine-config.cattle.io/v1',
    kind:         'VmwarevsphereConfig',
    metadata:     { name: `nc-${spec.name}-${z.zone}`, namespace: 'fleet-default' },
    cpuCount:     String(z.cpu),
    memorySize:   String(z.mem * 1024),  // GiB → MB
    diskSize:     String(z.disk * 1024), // GiB → MB
    datacenter:   v.datacenter,
    folder:       v.folder || '',
    pool:         v.pool || '',
    network:      [v.network],
    cloneFrom:    v.cloneFrom,
    creationType: 'template',
    os:           v.os || 'linux',
    sshUser:      z.sshUser || 'sles',
  };
  // Static-IP (Segment ohne DHCP, z.B. HAN-Witness): cloud-init network-config v2 via
  // guestinfo.metadata (base64) in cfgparam. Der metadata-Kanal ist von Rancher/CAPR
  // UNGENUTZT (der system-agent kommt über guestinfo.userdata) — kein Konflikt.
  // match.driver=vmxnet3 greift die Template-NIC, set-name normalisiert auf eth0.
  // gateway4 statt routes: bewusst — vom cloud-init im Leap-Micro-Template verstanden
  // (live bewiesen); Rand-Whitespace der Eingaben wird getrimmt.
  if (v.staticIp?.trim()) {
    // Defensiv (CMR-P3): render() kann auch ohne Wizard-validate() aufgerufen werden —
    // ohne Gateway wäre das gerenderte netplan unbrauchbar (etcd-Peers L3-unerreichbar).
    if (!(v.gateway || '').trim()) {
      throw new Error(`Zone ${z.zone}: staticIp ohne gateway — gateway ist Pflicht.`);
    }
    const dns = (v.dns || []).map((d) => d.trim()).filter(Boolean);
    const meta = [
      `instance-id: ${cfg.metadata.name}`,
      `local-hostname: ${cfg.metadata.name}`,
      'network:',
      '  version: 2',
      '  ethernets:',
      '    id0:',
      '      match:',
      '        driver: vmxnet3',
      '      set-name: eth0',
      '      addresses:',
      `        - ${v.staticIp.trim()}/${v.prefix ?? 24}`,
      `      gateway4: ${(v.gateway || '').trim()}`,
      ...(dns.length ? [
        '      nameservers:',
        '        addresses:',
        ...dns.map((d) => `          - ${d}`),
      ] : []),
      '',
    ].join('\n');
    // btoa im Browser (Rancher-UI-Extension); Buffer-Fallback für Node/Test-Kontexte.
    const b64 = typeof btoa !== 'undefined'
      ? btoa(meta)
      : Buffer.from(meta, 'utf-8').toString('base64');
    cfg.cfgparam = [
      `guestinfo.metadata=${b64}`,
      'guestinfo.metadata.encoding=base64',
    ];
  }
  // Datastore ODER datastoreCluster (genau eines), hostsystem optional.
  if (v.datastoreCluster) cfg.datastoreCluster = v.datastoreCluster;
  else if (v.datastore)   cfg.datastore = v.datastore;
  if (v.hostsystem)       cfg.hostsystem = v.hostsystem;
  return cfg;
}

function machinePools(spec: ClusterSpec) {
  const out: any[] = [];
  for (const z of spec.zones) {
    const cred = GD + z.credentialId;
    const ref = {
      kind: z.provider === 'vsphere' ? 'VmwarevsphereConfig' : 'HarvesterConfig',
      name: `nc-${spec.name}-${z.zone}`,
    };
    // ZWEI Zonen-Labels: topology.kubernetes.io/zone (Konvention) wird auf Site-A-Gast-
    // Nodes von einem Rancher-seitigen Sync mit Harvester-HOST-Zonen überschrieben
    // (Live-Befund 2026-07-02, Quelle offen) — focusnet.de/msp-zone ist der davon
    // unabhängige, stabile Key für Pod-Placement + CSI-Topology (Storage-Pinning).
    const labels = {
      'topology.kubernetes.io/zone': z.zone,
      'focusnet.de/msp-zone':        z.zone,
    };

    if (z.etcdOnly) {
      out.push({
        name: `etcd-${z.zone}`, etcdRole: true, controlPlaneRole: false, workerRole: false,
        quantity: 1, drainBeforeDelete: true, cloudCredentialSecretName: cred,
        machineConfigRef: ref, labels,
        // KEIN expliziter Taint: RKE2/CAPR taintet dedizierte etcd-Nodes (etcdRole ohne
        // cp/worker) SELBST mit node-role.kubernetes.io/etcd:NoExecute. Ein zusätzlicher
        // identischer Pool-Taint landete doppelt im kubelet-Drop-in → "duplicated taints
        // with the same key and effect" → rke2-server crash-loop (Live-RCA stretch-3site
        // HAN-Witness, 2026-07-02). Der Witness bleibt durch den automatischen Taint
        // workload-frei — Ziel-Zustand identisch.
      });
      continue;
    }
    if (z.cpQuantity > 0) {
      out.push({
        name: `cp-${z.zone}`, etcdRole: true, controlPlaneRole: true, workerRole: false,
        quantity: z.cpQuantity, drainBeforeDelete: true, cloudCredentialSecretName: cred,
        machineConfigRef: ref, labels,
      });
    }
    if (z.workerCount > 0) {
      out.push({
        name: `wk-${z.zone}`, etcdRole: false, controlPlaneRole: false, workerRole: true,
        quantity: z.workerCount, drainBeforeDelete: true, cloudCredentialSecretName: cred,
        machineConfigRef: ref, labels,
      });
    }
  }
  return out;
}

// Rendert das komplette Gast-Workload-Storage (ceph-csi-rbd + zonale SCs) als YAML für
// `additionalManifest`. Kern-Gotchas (alle live bewiesen, stretch-3site 2026-07-02):
//   - topology.enabled + domainLabels PFLICHT, sonst "no topology key found" beim
//     external-provisioner sobald eine SC allowedTopologies hat.
//   - ceph-csi schreibt domainLabels auf CSI-Keys um: focusnet.de/msp-zone →
//     topology.rbd.csi.ceph.com/msp-zone. SC-allowedTopologies MÜSSEN den CSI-Key
//     nutzen; kubelet spiegelt ihn als Node-Label NUR auf Nodes mit nodeplugin —
//     Witness-Nodes (etcd-Taint, keine Toleration) bekommen ihn nie.
// Sicherer YAML-Skalar: JSON-Strings sind valide double-quoted-YAML-Skalare inkl.
// Escaping von `"`/`\`/Steuerzeichen — keine YAML-Injection über Nutzereingaben
// (CMR-P2). Für NAMEN (zone) reicht das nicht (K8s-Namensregeln) — dort erzwingt
// die Invariante ^[a-z0-9-]{1,12}$, hier zusätzlich defensiv gefiltert.
function yq(v: string): string {
  return JSON.stringify(`${ v ?? '' }`.trim());
}
function safeName(v: string): string {
  return `${ v ?? '' }`.trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
}

function workloadCephManifest(wc: WorkloadCephSpec): string {
  const out: string[] = [
    'apiVersion: v1',
    'kind: Namespace',
    'metadata: { name: ceph-csi-rbd }',
  ];
  for (const [zoneRaw, zc] of Object.entries(wc.zones)) {
    const zone = safeName(zoneRaw);
    out.push(
      '---',
      'apiVersion: v1',
      'kind: Secret',
      'metadata:',
      `  name: csi-rbd-secret-${zone}`,
      '  namespace: ceph-csi-rbd',
      'stringData:',
      `  userID: ${yq(zc.userID)}`,
      `  userKey: ${yq(zc.userKey)}`,
    );
  }
  out.push(
    '---',
    'apiVersion: helm.cattle.io/v1',
    'kind: HelmChart',
    'metadata: { name: ceph-csi-rbd, namespace: kube-system }',
    'spec:',
    '  repo: https://ceph.github.io/csi-charts',
    '  chart: ceph-csi-rbd',
    '  targetNamespace: ceph-csi-rbd',
    '  valuesContent: |-',
    '    csiConfig:',
    `      - clusterID: ${yq(wc.clusterID)}`,
    '        monitors:',
    // Nur validierte/normalisierte Monitore rendern (leere raus, getrimmt) — die
    // Invariante prüft dieselbe Normalisierung inkl. Port-Range (CMR-P3).
    ...wc.monitors.map((m) => `${ m ?? '' }`.trim()).filter(Boolean).map((m) => `          - ${yq(m)}`),
    '    provisioner:',
    '      replicaCount: 2',
    '    storageClass:',
    '      create: false',
    '    topology:',
    '      enabled: true',
    '      domainLabels:',
    '        - focusnet.de/msp-zone',
  );
  for (const [zoneRaw, zc] of Object.entries(wc.zones)) {
    const zone = safeName(zoneRaw);
    out.push(
      '---',
      'apiVersion: storage.k8s.io/v1',
      'kind: StorageClass',
      `metadata: { name: ceph-rbd-${zone} }`,
      'provisioner: rbd.csi.ceph.com',
      'parameters:',
      `  clusterID: ${yq(wc.clusterID)}`,
      `  pool: ${yq(zc.pool)}`,
      '  imageFeatures: layering',
      '  csi.storage.k8s.io/fstype: ext4',
      `  csi.storage.k8s.io/provisioner-secret-name: csi-rbd-secret-${zone}`,
      '  csi.storage.k8s.io/provisioner-secret-namespace: ceph-csi-rbd',
      `  csi.storage.k8s.io/controller-expand-secret-name: csi-rbd-secret-${zone}`,
      '  csi.storage.k8s.io/controller-expand-secret-namespace: ceph-csi-rbd',
      `  csi.storage.k8s.io/node-stage-secret-name: csi-rbd-secret-${zone}`,
      '  csi.storage.k8s.io/node-stage-secret-namespace: ceph-csi-rbd',
      'reclaimPolicy: Delete',
      'allowVolumeExpansion: true',
      'volumeBindingMode: WaitForFirstConsumer',
      'allowedTopologies:',
      '  - matchLabelExpressions:',
      '      - key: topology.rbd.csi.ceph.com/msp-zone',
      `        values: ["${zone}"]`,
    );
  }
  out.push('');
  return out.join('\n');
}

export function render(spec: ClusterSpec) {
  const bp: any = blueprints;
  // Pro Zone providerabhängig dispatchen: Harvester-Insel ODER vSphere/vCenter (z.B. HAN-Witness).
  const machineConfigs = spec.zones.map((z) => (
    z.provider === 'vsphere' ? vsphereConfig(spec, z) : harvesterConfig(spec, z)
  ));

  const cluster = {
    apiVersion: 'provisioning.cattle.io/v1',
    kind:       'Cluster',
    metadata:   {
      name:      spec.name,
      namespace: 'fleet-default',
      labels:    { 'focusnet.de/stretch-host': 'true' },
      annotations: { 'field.cattle.io/description': 'Multi-Site stretched RKE2 (focusnet)' },
    },
    spec: {
      cloudCredentialSecretName: GD + spec.zones[0].credentialId,
      kubernetesVersion:         spec.k8sVersion,
      enableNetworkPolicy:       true,
      rkeConfig: {
        machineGlobalConfig: {
          // KEIN cloud-provider-name: der Default aktiviert RKE2s eingebauten
          // Cloud-Controller, der providerID (rke2://<node>) + Node-Adressen setzt —
          // Voraussetzung für Rancher machinenodelookup → addresses → join-url.
          // 'external' ohne deployetes CCM = Provisioning-Deadlock (s. RCA im Header).
          cni:                  'cilium',
          'disable-kube-proxy':  true,
          'cluster-cidr':        spec.podCidr,
          'service-cidr':        spec.serviceCidr,
          'etcd-arg':            bp.etcdArgs,
        },
        chartValues: {
          // bp.ciliumValues setzt k8sServiceHost=127.0.0.1 / k8sServicePort=6443 (PFLICHT):
          // mit disable-kube-proxy + kubeProxyReplacement gibt es beim Bootstrap weder
          // kube-proxy noch ein laufendes Cilium, das die kubernetes-ClusterIP (…43.0.1)
          // routet → Cilium-Operator/-Agent erreichen den apiserver sonst NICHT
          // ("no route to host") → CNI-Deadlock, Node NotReady (im PoC live verifiziert).
          // 127.0.0.1:6443 = RKE2-lokaler apiserver/Agent-LB auf JEDEM Node.
          'rke2-cilium': { ...bp.ciliumValues, routingMode: spec.routingMode },
        },
        machinePools:    machinePools(spec),
        upgradeStrategy: bp.upgradeStrategy,
        // Gast-Workload-Storage (ceph-csi + zonale SCs) nur wenn workloadCeph konfiguriert.
        // Der frühere uninitialized-Taint-/providerID-Resolver (DaemonSet) ist mit dem
        // eingebauten RKE2-Cloud-Controller gegenstandslos — ersatzlos entfernt (RCA s. Header).
        ...(spec.workloadCeph ? { additionalManifest: workloadCephManifest(spec.workloadCeph) } : {}),
      },
    },
  };

  return { machineConfigs, cluster };
}
