// Lese-/Schreib-Zugriff auf die Rancher-APIs.

// Cloud-Credentials AUSSCHLIESSLICH über die Norman-cloudCredential-API laden
// (wie die Rancher-eigene UI). KEIN roher Steve-Secret-Fallback (CMR-High):
// cloudCredential ist die kanonische API; liefert sie nichts, gibt es schlicht
// keine nutzbaren Harvester-Credentials zum Anzeigen — der rohe Secret-Pfad
// bräuchte breite Rechte und koppelt an Secret-Interna.
export async function listCloudCredentials(store: any) {
  const creds = await store.dispatch('rancher/findAll', { type: 'cloudCredential' });
  return (creds || [])
    .map((c: any) => {
      // Provider normalisieren (Alnum, lowercase): im Fallback-Pfad liefert Rancher
      // nur providerDisplay 'VMware vSphere' → 'vmwarevsphere', sonst würde der exakte
      // Vergleich vSphere-Credentials wegfiltern (CMR) und das Dropdown bliebe leer.
      const provider = `${ c?.provider || c?.providerDisplay || '' }`.toLowerCase().replace(/[^a-z0-9]/g, '');
      const fullId = `${ c?.id || '' }`;                 // z.B. 'cattle-global-data:cc-nxbxd'
      const bare = fullId.includes(':') ? fullId.split(':').pop() : (c?.metadata?.name || fullId);
      return {
        id:       bare,
        name:     c?.nameDisplay || c?.name || bare,
        provider,
        // Harvester-Mgmt-Cluster-Id (z.B. 'c-ddk4n') — Norman zeigt die non-sensitiven
        // credentialConfig-Felder; damit lassen sich Site-Ressourcen (VMImages, NADs,
        // Namespaces) über den Rancher-Proxy der Site laden (Dropdowns im Wizard).
        harvesterClusterId: c?.harvestercredentialConfig?.clusterId || '',
      };
    })
    // Nur Provider, die dieses Plugin unterstützt: Harvester-Inseln + vSphere (Witness).
    .filter((c: any) => c.id && (c.provider === 'harvester' || c.provider === 'vmwarevsphere'))
    .sort((a: any, b: any) => a.name.localeCompare(b.name));
}

// RKE2-Versionsliste aus dem Rancher-Release-Channel (gleiche Quelle wie die
// Cluster-Create-UI). Fehlschlag → leere Liste: der Wizard degradiert dann zu
// Freitext (datalist bleibt einfach leer) statt zu blockieren.
export async function listRke2Versions(store: any): Promise<string[]> {
  try {
    const res = await store.dispatch('management/request', { url: '/v1-rke2-release/releases' });
    const data = res?.data || [];
    return data
      .map((r: any) => r?.id || r?.version)
      .filter((v: any) => typeof v === 'string' && v.includes('rke2'))
      .reverse(); // neueste zuerst
  } catch (e) {
    return [];
  }
}

// Site-Ressourcen einer Harvester-Insel über den Rancher-Cluster-Proxy laden
// (Dropdowns: VMImages, VM-Netze/NADs, Namespaces). Jede Teil-Liste degradiert
// bei Fehler einzeln zu [] — der Wizard zeigt dann Freitext-Inputs (fail-open UI,
// harte Gates bleiben die Invarianten).
export async function listHarvesterSiteResources(store: any, clusterId: string) {
  // clusterId stammt aus credentialConfig — strikt allowlisten (Rancher-Mgmt-Cluster-
  // Ids sind 'local' oder 'c-…'), sonst könnte ein manipuliertes Credential den
  // Request-Pfad verbiegen (CMR-P2). Zusätzlich path-segment-encoded interpolieren.
  if (!/^(local|c-[a-z0-9-]+)$/.test(`${ clusterId }`)) {
    return { images: [], networks: [], namespaces: [] };
  }
  const base = `/k8s/clusters/${ encodeURIComponent(clusterId) }/v1`;
  const fetchList = async (path: string) => {
    try {
      const res = await store.dispatch('management/request', { url: `${ base }/${ path }` });
      return res?.data || [];
    } catch (e) {
      return [];
    }
  };
  const [imgs, nads, nss] = await Promise.all([
    fetchList('harvesterhci.io.virtualmachineimages'),
    fetchList('k8s.cni.cncf.io.network-attachment-definitions'),
    fetchList('namespaces'),
  ]);
  return {
    images: imgs.map((i: any) => ({
      id:       `${ i?.metadata?.namespace }/${ i?.metadata?.name }`,
      label:    i?.spec?.displayName || i?.metadata?.name,
      // targetStorageClassName sichtbar machen — Ceph-Images (rook-…-rbd) sind so
      // im Dropdown direkt erkennbar (nodeStorage=ceph braucht genau solche).
      targetSc: i?.spec?.targetStorageClassName || '',
    })),
    networks:   nads.map((n: any) => `${ n?.metadata?.namespace }/${ n?.metadata?.name }`),
    namespaces: nss.map((n: any) => n?.metadata?.name).filter((n: string) => n && !n.startsWith('cattle-') && !n.startsWith('kube-')),
  };
}

// Ceph-Workload-Parameter einer Harvester-Site AUTOMATISCH ermitteln — Kunden dürfen
// keine Ceph-Interna (fsid/Monitore/Pool/cephx) eingeben müssen (User-Anforderung).
// Quellen (alle live verifiziert, 2026-07-02): rook-CSI-StorageClass der Site
// (provisioner rook-ceph-*.rbd.csi.ceph.com → pool/clusterID/secret-NS), ConfigMap
// `ceph-csi-config` im Consumer-NS (Monitore), Secret `csi-rbd-secret` (cephx).
// Jeder Fehlpfad → null: die Zone zeigt dann „kein Ceph verfügbar" und die
// Invarianten blockieren das Aktivieren.
export async function discoverZoneCeph(store: any, clusterId: string) {
  if (!/^(local|c-[a-z0-9-]+)$/.test(`${ clusterId }`)) {
    return null;
  }
  const base = `/k8s/clusters/${ encodeURIComponent(clusterId) }/v1`;
  const req = async (url: string) => {
    try {
      return await store.dispatch('management/request', { url });
    } catch (e) {
      return null;
    }
  };
  const scs = (await req(`${ base }/storage.k8s.io.storageclasses`))?.data || [];
  const candidates = scs
    .filter((s: any) => {
      const prov = `${ s?.provisioner || '' }`;
      return prov.endsWith('rbd.csi.ceph.com') && prov !== 'rbd.csi.ceph.com' &&
        s?.parameters?.pool && s?.parameters?.clusterID;
    })
    // deterministisch sortieren (API-Reihenfolge ist es nicht) — CMR-P2.
    .sort((a: any, b: any) => `${ a?.metadata?.name }`.localeCompare(`${ b?.metadata?.name }`));
  if (!candidates.length) {
    return null;
  }
  // Mehrdeutigkeit: nur akzeptieren, wenn ALLE Kandidaten auf dieselbe Kombination
  // (clusterID, pool, secret-NS) zeigen — sonst wäre die Wahl willkürlich und könnte
  // den falschen Pool/cephx-User erwischen → lieber null (Zone meldet „kein Storage",
  // Betreiber muss die Site eindeutig machen). CMR-P2.
  const keyOf = (s: any) => `${ s.parameters.clusterID }|${ s.parameters.pool }|${ s.parameters['csi.storage.k8s.io/provisioner-secret-namespace'] }`;
  if (new Set(candidates.map(keyOf)).size > 1) {
    return null;
  }
  const sc = candidates[0];
  const ns = sc.parameters['csi.storage.k8s.io/provisioner-secret-namespace'];
  const secretName = sc.parameters['csi.storage.k8s.io/provisioner-secret-name'] || 'csi-rbd-secret';
  if (!ns) {
    return null;
  }
  const [cm, sec] = await Promise.all([
    req(`${ base }/configmaps/${ encodeURIComponent(ns) }/ceph-csi-config`),
    req(`${ base }/secrets/${ encodeURIComponent(ns) }/${ encodeURIComponent(secretName) }`),
  ]);
  let monitors: string[] = [];
  try {
    const cfg = JSON.parse(cm?.data?.['config.json'] || '[]');
    // NUR der exakt zur SC-clusterID passende Eintrag zählt — ein cfg[0]-Fallback
    // könnte Monitore eines FREMDEN Ceph mit unserer clusterID kombinieren (CMR-P2).
    const entry = Array.isArray(cfg) ? cfg.find((c: any) => c?.clusterID === sc.parameters.clusterID) : null;
    monitors = Array.isArray(entry?.monitors) ? entry.monitors : [];
  } catch (e) {
    monitors = [];
  }
  const b64 = (v: string) => {
    try {
      return atob(v || '');
    } catch (e) {
      return '';
    }
  };
  const userID = b64(sec?.data?.userID);
  const userKey = b64(sec?.data?.userKey);
  if (!monitors.length || !userID || !userKey) {
    return null;
  }
  return {
    clusterID: sc.parameters.clusterID,
    monitors,
    pool:      sc.parameters.pool,
    userID,
    userKey,
    hostStorageClass: sc.metadata?.name || '',
  };
}

// Steve-Typ je MachineConfig-kind (HarvesterConfig | VmwarevsphereConfig).
function steveTypeForKind(kind: string): string {
  const plural: Record<string, string> = {
    HarvesterConfig:     'harvesterconfigs',
    VmwarevsphereConfig: 'vmwarevsphereconfigs',
  };
  const p = plural[kind];
  if (!p) {
    throw new Error(`Unbekannter MachineConfig-kind: ${ kind }`);
  }
  return `rke-machine-config.cattle.io.${ p }`;
}

// Upsert: POST; bei 409 (existiert bereits) per PUT aktualisieren — sonst würde
// ein Retry mit geänderter Image/CPU/RAM stillschweigend die stale Config
// wiederverwenden (CMR-Medium). Typ wird aus mc.kind abgeleitet (provider-agnostisch).
// vCenter-Inventar für die vSphere-Platzierungs-Dropdowns — exakt die /meta/vsphere-
// Endpunkte, die auch Ranchers eigener vSphere-Wizard nutzt (dashboard
// shell/machine-config/vmwarevsphere.vue): 'data-centers' OHNE, alle übrigen Ressourcen
// MIT dataCenter-Parameter; 'templates' ist die cloneFrom-Quelle für creationType=template
// (NICHT 'virtual-machines' — das wäre der vm-Klon-Pfad). Pfad-Ressourcen sind Strings
// und werden unverändert als Config-Werte übernommen (der Node-Driver akzeptiert Pfade
// wie Namen). Netzwerke kommen aus 'networks-extended' als {name, moid} — gebunden wird
// der MOID (eindeutig bei gleichnamigen PortGroups; Rancher-≥2.10-Konvention, CMR-P2),
// das Label bleibt lesbar `name (moid)`. Jeder Fehlpfad (Rechte, vCenter down) → leere
// Listen: der Wizard fällt je Feld auf Freitext zurück (fail-open wie Harvester-Dropdowns).
export async function discoverVsphereInventory(store: any, credentialId: string, dataCenter?: string) {
  const bare = `${ credentialId ?? '' }`.trim();
  const fullCredId = bare.includes(':') ? bare : `cattle-global-data:${ bare }`;
  const fetchMeta = async (resource: string): Promise<any[]> => {
    try {
      const params = [`cloudCredentialId=${ encodeURIComponent(fullCredId) }`];
      if (dataCenter) {
        params.push(`dataCenter=${ encodeURIComponent(dataCenter) }`);
      }
      const res = await store.dispatch('management/request', {
        url:                  `/meta/vsphere/${ resource }?${ params.join('&') }`,
        redirectUnauthorized: false,
      });
      return res?.data || [];
    } catch (e) {
      return [];
    }
  };
  const asStrings = (arr: any[]) => arr.map((o: any) => `${ o }`.trim()).filter(Boolean);
  if (!dataCenter) {
    return { dataCenters: asStrings(await fetchMeta('data-centers')) };
  }
  const [dataStores, dataStoreClusters, pools, folders, networksExt, templates] = await Promise.all([
    fetchMeta('data-stores'),
    fetchMeta('data-store-clusters'),
    fetchMeta('resource-pools'),
    fetchMeta('folders'),
    fetchMeta('networks-extended'),
    fetchMeta('templates'),
  ]);
  const networks = networksExt
    .map((o: any) => ({ name: `${ o?.name ?? '' }`.trim(), moid: `${ o?.moid ?? '' }`.trim() }))
    .filter((o: any) => o.name && o.moid)
    .map((o: any) => ({ label: `${ o.name } (${ o.moid })`, value: o.moid }));
  return {
    dataStores:        asStrings(dataStores),
    dataStoreClusters: asStrings(dataStoreClusters),
    pools:             asStrings(pools),
    folders:           asStrings(folders),
    networks,
    templates:         asStrings(templates),
  };
}

export async function postMachineConfig(store: any, mc: any) {
  const ns = mc.metadata.namespace;
  const name = mc.metadata.name;
  const type = steveTypeForKind(mc.kind);
  try {
    return await store.dispatch('management/request', {
      url: `/v1/${ type }`, method: 'POST', data: mc,
    });
  } catch (e: any) {
    const status = e?.status || e?.response?.status;
    if (status !== 409) {
      throw e;
    }
    const cur = await store.dispatch('management/request', {
      url: `/v1/${ type }/${ ns }/${ name }`, method: 'GET',
    });
    const merged = {
      ...mc,
      metadata: { ...mc.metadata, resourceVersion: cur?.metadata?.resourceVersion },
    };
    return store.dispatch('management/request', {
      url: `/v1/${ type }/${ ns }/${ name }`, method: 'PUT', data: merged,
    });
  }
}

export async function postCluster(store: any, cluster: any) {
  return store.dispatch('management/request', {
    url: '/v1/provisioning.cattle.io.clusters', method: 'POST', data: cluster,
  });
}

export async function getClusterStatus(store: any, name: string) {
  const res = await store.dispatch('management/request', {
    url: `/v1/provisioning.cattle.io.clusters/fleet-default/${ name }`, method: 'GET',
  });
  return { ready: res?.status?.ready === true, raw: res };
}
